<template><div class="app-container"><el-card><div slot="header">我的持仓</div><el-table :data="rows"><el-table-column prop="stockCode" label="代码"/><el-table-column prop="costPrice" label="成本价"/><el-table-column prop="quantity" label="持仓数量"/><el-table-column label="操作"><template slot-scope="s"><el-button type="text" @click="openEdit(s.row)">编辑</el-button><el-button type="text" @click="analyze(s.row,false)">分析</el-button><el-button type="text" @click="analyze(s.row,true)">AI分析</el-button></template></el-table-column></el-table></el-card><el-dialog title="编辑持仓" :visible.sync="visible" width="420px"><el-form :model="edit"><el-form-item label="股票代码"><el-input v-model="edit.stockCode" disabled/></el-form-item><el-form-item label="成本价"><el-input v-model="edit.costPrice"/></el-form-item><el-form-item label="持仓数量"><el-input v-model="edit.quantity"/></el-form-item></el-form><div slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="saveEdit">保存</el-button></div></el-dialog></div></template>
<script>import{listPosition,updatePosition,analyzePosition}from'@/api/stock/position';export default{name:'StockPosition',data(){return{rows:[],visible:false,edit:{},result:null}},created(){this.load()},methods:{load(){listPosition().then(r=>this.rows=r.data)},openEdit(r){this.edit={positionId:r.positionId,stockCode:r.stockCode,stockName:r.stockName,costPrice:r.costPrice,quantity:r.quantity};this.visible=true},saveEdit(){if(!(this.edit.costPrice>0&&this.edit.quantity>0))return this.$modal.msgWarning('成本价和数量必须大于零');updatePosition(this.edit).then(()=>{this.$modal.msgSuccess('保存成功');this.visible=false;this.load()})},analyze(r,ai){analyzePosition(r.positionId,ai).then(x=>this.result=x.data)}}}</script>
